func (w *WorkBookRels) MakeXLSXWorkbookRels() xlsxWorkbookRels {
	relCount := len(*w)
	xWorkbookRels := xlsxWorkbookRels{}
	xWorkbookRels.Relationships = make([]xlsxWorkbookRelation, relCount + 2)
	for k, v := range(*w) {
		index, err := strconv.Atoi(k[3:len(k)])
		if err != nil {
			panic(err.Error())
		}
