		case *TypeVariable:
			if a2.Id == b2.Id {
				return a2
			}
		case *TypeOperator:
			a2.Instance = &b1
			return b1
		}
	case *TypeOperator:
		switch b2 := b1.(type) {
		case *TypeVariable:
